def secure_tables() -> None:
    """Second wall behind the tenant filter in every query.

    - Row-level security: the app role sees and writes only rows of the tenant
      set with ``SET LOCAL app.tenant_id`` for the current transaction. Unset
      -> no rows at all (fail closed).
    - Least privilege: the app role may not UPDATE/DELETE append-only tables
      and may only read tenants and tax rates.
    The table owner (migrations, admin CLI) is not affected by RLS.
    """
    for table in TENANT_TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY tenant_isolation ON {table} "
            f"USING (tenant_id = current_setting('app.tenant_id', true)) "
            f"WITH CHECK (tenant_id = current_setting('app.tenant_id', true))"
        )
    grants = [f"GRANT SELECT ON {t} TO {APP_ROLE}" for t in READ_ONLY_TABLES]
    for table in TENANT_TABLES:
        verbs = "SELECT, INSERT" if table in APPEND_ONLY_TABLES else "SELECT, INSERT, UPDATE, DELETE"
        grants.append(f"GRANT {verbs} ON {table} TO {APP_ROLE}")
    grants.append(f"GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO {APP_ROLE}")
    body = "; ".join(grants)
    # The role is created by the operator (it needs a password); skip grants
    # where it does not exist so the schema can still be built.
    op.execute(f"DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{APP_ROLE}') "
               f"THEN {body}; END IF; END $$")


